const box = document.getElementById('ai4a11y-agent-watch');
if (!box) return true;

const gate = box.querySelector('.aw-gate');
if (!gate) return false;
if (gate.getAttribute('role') !== 'alertdialog') return false;

const describedby = gate.getAttribute('aria-describedby');
const msg = document.getElementById(describedby);
if (!msg || !msg.textContent.includes('Approve $89 purchase?')) return false;

const buttons = gate.querySelectorAll('button');
if (!buttons.length) return false;
for (const btn of buttons) {
  btn.focus();
  if (document.activeElement !== btn) return false;
  const rect = btn.getBoundingClientRect();
  if (rect.width < 24 || rect.height < 24) return false;
}

